import{_ as e,o,c as i,a2 as t}from"./chunks/framework.iXqqCa-C.js";const l="/images/bot-dm-start.webp",r="/images/bot-dm-follow.webp",s="/images/bot-dm-inbox.webp",c="/images/migration-export.webp",d="/images/migration-download.webp",n="/images/migration-style.webp",p="/images/migration-memory.webp",h="/images/migration-import.webp",m="/images/migration-draw.webp",x=JSON.parse('{"title":"从旧版 Aliya Bot 迁移","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration.md","filePath":"guide/migration.md","lastUpdated":1793029602000}'),g={name:"guide/migration.md"};function u(_,a,b,f,y,q){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="从旧版-aliya-bot-迁移" tabindex="-1">从旧版 Aliya Bot 迁移 <a class="header-anchor" href="#从旧版-aliya-bot-迁移" aria-label="Permalink to &quot;从旧版 Aliya Bot 迁移&quot;">​</a></h1><p>本章面向仍在使用旧版 Aliya Bot 的用户。旧版的剩余额度和聊天记录都可以迁移到社区的智能体服务，见<a href="#额度迁移">额度迁移</a>和<a href="#聊天记录迁移">聊天记录迁移</a>。</p><h2 id="发起私信" tabindex="-1">发起私信 <a class="header-anchor" href="#发起私信" aria-label="Permalink to &quot;发起私信&quot;">​</a></h2><p>通过 Misskey，您可以轻松地与 Aliya 建立联系。</p><p>如果您需要向此前未曾与之聊天过的用户发起私信，请访问 Misskey 主页，依次点击 <strong>发现 – 用户 – 用户头像</strong>。</p><p><img src="'+l+'" alt="发现用户并发起私信"></p><p>进入个人资料后，由于用户隐私政策，需要关注用户后才能发起私信。因此，请先关注用户，然后点击右上角三个点 – 私信。</p><p><img src="'+r+'" alt="关注 Aliya（谢谢喵）"></p><p>如果需要再次进入聊天，只需在左侧菜单栏找到 <strong>消息</strong> 并点击即可。</p><p><img src="'+s+'" alt="进入私聊"></p><h2 id="常用指令" tabindex="-1">常用指令 <a class="header-anchor" href="#常用指令" aria-label="Permalink to &quot;常用指令&quot;">​</a></h2><h3 id="会话相关" tabindex="-1">会话相关 <a class="header-anchor" href="#会话相关" aria-label="Permalink to &quot;会话相关&quot;">​</a></h3><ul><li><code>/ls</code>（无参数）：查看当前会话的对话列表。</li><li><code>/new</code>（无参数）：创建一个新的对话，原对话记录将保留。</li><li><code>/rename 文字</code>：重命名当前对话。</li><li><code>/switch 序号</code>：在多个对话历史之间进行切换。 <ul><li>注：序号为对话名称前面的数字。</li></ul></li><li><code>/del</code>（无参数）：将当前对话从对话记录中删除。 <ul><li>警告：该操作不可逆！</li></ul></li></ul><h3 id="功能相关" tabindex="-1">功能相关 <a class="header-anchor" href="#功能相关" aria-label="Permalink to &quot;功能相关&quot;">​</a></h3><ul><li><code>/ch 数量</code>：遗忘最近指定数量的对话，若未指定则默认为 1。</li><li><code>/draw</code>（根命令）：用于查询、更改画图工具状态，详情请发送 <code>/draw</code>。</li><li><code>/hg</code>（无参数）：查询当前 Aliya 对您的好感度。</li><li><code>/model</code>（根命令）：查询、更改当前对话模型状态（当前使用的模型、额度等），详情请发送 <code>/model</code>。</li><li><code>/rc</code>（根命令）：查询日程提醒，详情请发送 <code>/rc</code>。</li><li><code>/time</code>（根命令）：时间系统，用于查询、修改您和 Aliya 的时间线，详情请发送 <code>/time</code>。</li><li><code>/xf</code>（无参数）：修复当前对话。</li><li><code>/yh</code>（无参数）：若对话质量较低，请尝试发送此命令进行优化，再次发送可关闭优化。 <ul><li>注：开启优化可能会增加您的 tokens 或额度用量。</li></ul></li></ul><h2 id="额度迁移" tabindex="-1">额度迁移 <a class="header-anchor" href="#额度迁移" aria-label="Permalink to &quot;额度迁移&quot;">​</a></h2><p>旧版 Aliya Bot 的剩余额度可以迁移到智能体服务：向 Aliya Bot（不是智能体里的 Aliya 角色）发送指令 <code>/credits_transfer</code>，剩余额度会一次性转入智能体余额。</p><p>迁移记录可在「智能体 → 我的用量 → 消费日志」中查看，见<a href="/guide/agent/usage#我的用量">用量与额度</a>。</p><h2 id="聊天记录迁移" tabindex="-1">聊天记录迁移 <a class="header-anchor" href="#聊天记录迁移" aria-label="Permalink to &quot;聊天记录迁移&quot;">​</a></h2><p>把 Aliya Bot 的聊天记录导入智能体的 Aliya 角色。</p><h3 id="_1-导出聊天记录" tabindex="-1">1. 导出聊天记录 <a class="header-anchor" href="#_1-导出聊天记录" aria-label="Permalink to &quot;1. 导出聊天记录&quot;">​</a></h3><p>向 Aliya Bot 发送 <code>/export_context</code> 指令，下载聊天记录文件。</p><p><img src="'+c+'" alt="导出聊天记录"></p><h3 id="_2-创建新会话" tabindex="-1">2. 创建新会话 <a class="header-anchor" href="#_2-创建新会话" aria-label="Permalink to &quot;2. 创建新会话&quot;">​</a></h3><p>在「智能体 → 广场」找到 Aliya 角色，点击「开始聊天」，创建新的会话。</p><p><img src="'+d+'" alt="在广场找到 Aliya" class="phone-shot"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>请务必创建新会话，避免已有会话的聊天记忆被覆盖。</p></div><h3 id="_3-完成会话配置" tabindex="-1">3. 完成会话配置 <a class="header-anchor" href="#_3-完成会话配置" aria-label="Permalink to &quot;3. 完成会话配置&quot;">​</a></h3><p>在新会话顶部的标签页中依次完成以下配置。</p><p><strong>① 选择对话风格</strong>：任意社区风格均可。如果列表里没有可选的风格，先到「智能体 → 广场 → 对话风格」添加，见<a href="/guide/agent/styles">对话风格</a>。</p><p><img src="'+n+'" alt="选择对话风格" class="phone-shot"></p><p><strong>② 开启记忆</strong>：在「记忆」标签页选择长期记忆方式，推荐「便签压缩」。模型的上下文长度有限，不开启记忆时，超出上下文的旧对话不会再发给模型。详见<a href="/guide/agent/memory">记忆</a>。</p><p><img src="'+p+'" alt="开启记忆" class="phone-shot"></p><p><strong>③ 开启分段输出</strong>（可选）：在「会话」标签页打开「分段输出」。</p><p><strong>④ 导入聊天记录</strong>：在「会话」标签页点击「导入并覆盖」，上传第 1 步下载的文件。导入会覆盖当前会话的消息。</p><p><img src="'+h+'" alt="导入聊天记录" class="phone-shot"></p><p><strong>⑤ 开启生图</strong>（可选）：在「生图」标签页选择生图模型，角色回复时会附带插图。「画师串」用于切换画面风格。详见<a href="/guide/agent/chat#生图">生图</a>。</p><p><img src="'+m+'" alt="生图配置" class="phone-shot"></p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>迁移中遇到问题，可以<a href="/guide/faq#联系项目组">联系项目组</a>。</p>',40)])])}const k=e(g,[["render",u]]);export{x as __pageData,k as default};
